<?php

declare(strict_types=1);

namespace App\Data\Macro;

/**
 * Capital-goods price drift by industry, against the GDP deflator. Generated by var/harness/capgoods/capgoods.py;
 * regenerate, do not edit.
 *
 * Implicit price of each industry's net stock of private fixed assets (BEA Fixed Assets Table 3.1ESI current cost over
 * Table 3.2ESI chain-type quantity, year-end), annual log drift 2009-2019, less the GDP deflator's Q4/Q4 drift over
 * the same decade (0.0163). A negative drift is a capital good getting cheaper against what it produces.
 * Keyed by business model; a model not listed takes its nearest listed parent, then the all-industry figure.
 */
final class CapitalGoodsPrices
{
    /** Every industry but real estate (mostly housing): the plant of a firm with no sector physics. */
    public const ALL_INDUSTRIES_DRIFT = 0.0006;

    /** Annual drift by business model, with the BEA industries it is measured on. */
    public const DRIFT_BY_MODEL = [
        // Miscellaneous professional, scientific, and technical services \4\
        'AdvertisingAgencyBusinessModel' => -0.0047,
        'ApparelManufacturingBusinessModel' => 0.0033, // Apparel and leather and allied products
        'AutoManufacturerBusinessModel' => -0.0006, // Motor vehicles, bodies and trailers, and parts
        'BiotechBusinessModel' => 0.0022, // Chemical products
        'ChemicalBusinessModel' => 0.0022, // Chemical products
        'CommunicationEquipmentBusinessModel' => -0.0005, // Computer and electronic products
        'ComputerHardwareBusinessModel' => -0.0005, // Computer and electronic products
        'ConglomerateBusinessModel' => 0.0002, // Durable goods
        'ConstructionBusinessModel' => -0.0005, // Construction
        'ConsumerStaplesBusinessModel' => 0.0010, // Food and beverage and tobacco products
        'DefenseContractorBusinessModel' => 0.0026, // Other transportation equipment
        'EducationBusinessModel' => 0.0071, // Educational services
        'FinancialDataBusinessModel' => -0.0189, // Information and data processing services
        'HeavyManufacturingBusinessModel' => 0.0003, // Machinery
        'HomebuilderBusinessModel' => -0.0005, // Construction
        'InternetRetailBusinessModel' => 0.0030, // Other retail
        'LawFirmBusinessModel' => -0.0052, // Legal services
        // Truck transportation, Other transportation and support activities \2\, Warehousing and storage
        'LogisticsBusinessModel' => 0.0009,
        'LuxuryBusinessModel' => 0.0009, // Other manufacturing
        'MedicalCareFacilityBusinessModel' => -0.0053, // Health and social assistance
        'MerchantHouseBusinessModel' => -0.0014, // Wholesale trade
        'MiningBusinessModel' => 0.0103, // Mining, except oil and gas
        'OilGasProducerBusinessModel' => 0.0067, // Oil and gas extraction
        'RailroadBusinessModel' => -0.0004, // Railroad transportation
        'RefiningBusinessModel' => 0.0006, // Petroleum and coal products
        'ReitBusinessModel' => 0.0147, // Real estate
        'ResortsCasinosBusinessModel' => 0.0134, // Amusements, gambling, and recreation industries, Accommodation
        'RestaurantBusinessModel' => 0.0047, // Food services and drinking places
        'SecurityProtectionBusinessModel' => -0.0107, // Administrative and support services
        'SemiconductorBusinessModel' => -0.0005, // Computer and electronic products
        'ShippingBusinessModel' => -0.0040, // Water transportation
        'SpecialtyIndustrialMachineryBusinessModel' => 0.0003, // Machinery
        'SteelManufacturingBusinessModel' => 0.0005, // Primary metals
        'TechBusinessModel' => -0.0189, // Information and data processing services
        'TelecomBusinessModel' => -0.0203, // Broadcasting and telecommunications
        'ToolsAndAccessoriesBusinessModel' => -0.0024, // Fabricated metal products, Durable goods
        'UtilityBusinessModel' => 0.0057, // Utilities
        'WasteManagementBusinessModel' => 0.0059, // Waste management and remediation services
    ];

    /** The drift for a business model, walking up its parents to the nearest one measured. */
    public static function driftFor(object $model): float
    {
        for ($class = $model::class; $class !== false; $class = get_parent_class($class)) {
            $short = substr($class, (int) strrpos($class, '\\') + 1);
            if (isset(self::DRIFT_BY_MODEL[$short])) {
                return self::DRIFT_BY_MODEL[$short];
            }
        }

        return self::ALL_INDUSTRIES_DRIFT;
    }
}
